  "REQUEST":{
    "ACTION": "CREATE",
    "DATA": REQUEST.DATA.productionSetupQualitySubjectLists.edges.node.(
      $workOrderId := workOrderId;
      $workOrderProcessId := workOrderProcessId;
      $specificationGroupId := qualitySubjectList.specificationGroup.id;
      $qualitySubjectListId := qualitySubjectListId;
      $quantity := qualitySubjectList.interval.quantity;
      $repeat:= qualitySubjectList.interval.repeat;
      $producedQuantity := $$.REQUEST.DATA.producedQuantity;
      $specGroupReports := $count(qualitySubjectList.specificationGroup.qualityReports.edges);
      $reportTrigger := $repeat ? ($specGroupReports + 1) * $quantity : $quantity;
      $reportsToCreate := $repeat ? $floor(($producedQuantity - $specGroupReports * $quantity) / $quantity) : 1;
      $producedQuantity >= $reportTrigger and $not($repeat = false and $specGroupReports >= 1) ? [1..$reportsToCreate].(
        {
          "qualitySpecificationGroupId": $specificationGroupId,
          "productionRunId": $$.REQUEST.DATA.productionRunId,
          "qualitySubjectListId": $qualitySubjectListId,
          "workOrderId": $workOrderId,
          "workOrderProcessId": $workOrderProcessId
        }
      );
    )
  }

}

