(

  $productId := $state.context.LOCAL.destinationProductId;
  {
    "where": {
     "_and": [
        {
          "lotControlId": {
            "_isNull": true

          }
        },
        {
          "processId": {
            "_isNull": true
          }
        },
        {
          "productId": $isNotNilOrEmpty($productId) ? {
            "_eq": $productId
          } : {
            "_isNull": true
          }
        },
        {
          "productProcessId":{
            "_isNull": true
          }
        },

        {
          "workcenterId": {
            "_isNull": true
          }
        },
        {
           "usable": {
             "_eq": true
           }
        },
        {
          "interval":{
            "_and": [
              {
                "transactionTypeId": {
                  "_eq":  $state.context.LOCAL.transactionTypeId
              }

              },
              {
                "qualityIntervalTypeId": {
                  "_eq": "OnTransaction"
                }
              }
            ]
          }
        }
      ]
    }
  }
)

