query Query($wherePR: ProductionRunWhereInput, $whereQRI: QualityReportInventoryWhereInput) {
  productionRun(where: $wherePR) {
    edges {
      node {
        id
        productionHistories{
          edges{
            node{
              inventoryId
            }
          }
        }
      }
    }
  }
  qualityReportInventory(where: $whereQRI) {
    edges {
      node {
        id
        inventoryId
        qualityReportId
      }
    }
  }
}

